def compute_forecast(opportunities):
    forecast = {}
    for opportunity in opportunities:
        stage = opportunity.get('StageName', 'Unknown')
        amount = opportunity.get('Amount', 0)
        if stage not in forecast:
            forecast[stage] = 0
        forecast[stage] += amount
    return forecast

