import json
import datetime

def compute_secret_drift(doppler_secrets, github_secrets):
    drift = []
    github_secret_names = {secret['name'] for secret in github_secrets}
    for secret in doppler_secrets:
        last_updated = datetime.datetime.fromisoformat(secret['last_updated'].replace('Z', '+00:00'))
        age_days = (datetime.datetime.now(datetime.timezone.utc) - last_updated).days
        if secret['name'] not in github_secret_names:
            drift.append({'name': secret['name'], 'status': 'missing in GitHub', 'age_days': age_days})
        elif age_days > 30:
            drift.append({'name': secret['name'], 'status': 'rotation overdue', 'age_days': age_days})
    return drift

rotation_drift = compute_secret_drift(secrets, github_secrets)

