import json

def cluster_keywords(raw_keywords):
    clusters = {}
    for keyword in raw_keywords:
        # Simple clustering based on keyword prefix
        prefix = keyword.split()[0]
        if prefix not in clusters:
            clusters[prefix] = []
        clusters[prefix].append(keyword)
    return list(clusters.values())

raw_keywords = ['python tutorial', 'python for data science', 'javascript tutorial', 'javascript for beginners']
clusters = cluster_keywords(raw_keywords)

