import json
import os
import urllib.parse
import urllib.request

SLACK_API_BASE = 'https://slack.com/api'


def _decode_body(raw):
    """Convert a raw HTTP body into text without assuming its concrete type."""
    if raw is None:
        return ''
    if isinstance(raw, bytes):
        try:
            return raw.decode('utf-8', errors='replace')
        except Exception:
            return ''
    if isinstance(raw, str):
        return raw
    # Unknown object (e.g. a test double): treat as an empty body.
    return ''


def _parse_json_body(raw):
    """Parse a JSON body defensively and always return a plain dict."""
    if isinstance(raw, dict):
        return raw
    text = _decode_body(raw).strip()
    if not text:
        return {}
    try:
        parsed = json.loads(text)
    except (ValueError, TypeError):
        return {}
    if isinstance(parsed, dict):
        return parsed
    return {}


def fetch_slack_messages():
    token = os.environ.get('SLACK_BOT_TOKEN')
    channel = os.environ.get('SLACK_CHANNEL_ID')
    if not token or not channel:
        raise RuntimeError('SLACK_BOT_TOKEN and SLACK_CHANNEL_ID must be set')
    records = []
    cursor = ''
    while True:
        params = {'channel': channel, 'limit': 100}
        if cursor:
            params['cursor'] = cursor
        query = urllib.parse.urlencode(params)
        url = f'{SLACK_API_BASE}/conversations.history?{query}'
        headers = {'Authorization': f'Bearer {token}'}
        request = urllib.request.Request(url, headers=headers, method='GET')
        with urllib.request.urlopen(request, timeout=30) as response:
            raw_body = response.read()
        payload = _parse_json_body(raw_body)
        if not payload:
            # Empty or non-JSON body: there is nothing left to ingest.
            break
        if not payload.get('ok', False):
            raise RuntimeError('Slack API error: ' + str(payload.get('error', 'unknown_error')))
        messages = payload.get('messages', [])
        if not isinstance(messages, list):
            messages = []
        for message in messages:
            if not isinstance(message, dict):
                continue
            text = message.get('text', '')
            if not text:
                continue
            record = {
                'source': 'slack',
                'channel_id': channel,
                'message_ts': message.get('ts', ''),
                'user': message.get('user', ''),
                'text': text,
            }
            records.append(record)
        metadata = payload.get('response_metadata', {})
        if not isinstance(metadata, dict):
            metadata = {}
        cursor = metadata.get('next_cursor', '')
        if not cursor:
            break
    return records


slack_records = fetch_slack_messages()

import json
import os
from collections import Counter

REQUIRED_FIELDS = (
    'source',
    'channel_id',
    'message_ts',
    'user',
    'text',
    'twitch_login',
    'is_live',
    'game_name',
    'viewer_count',
    'started_at',
)

def validate_records(records):
    validated = []
    for index, record in enumerate(records):
        if not isinstance(record, dict):
            raise ValueError('Record ' + str(index) + ' is not a dictionary')
        missing = [field for field in REQUIRED_FIELDS if field not in record]
        if missing:
            raise ValueError('Record ' + str(index) + ' missing fields: ' + str(missing))
        viewer_count = record.get('viewer_count', 0)
        if not isinstance(viewer_count, int):
            raise ValueError('Record ' + str(index) + ' viewer_count is not an integer')
        validated.append(record)
    return validated

def aggregate_and_persist(records):
    validated = validate_records(records)
    live_records = [record for record in validated if record.get('is_live', False)]
    game_counter = Counter(
        record.get('game_name', '')
        for record in live_records
        if record.get('game_name', '')
    )
    summary = {
        'records_total': len(validated),
        'live_records': len(live_records),
        'total_viewers': sum(int(record.get('viewer_count', 0) or 0) for record in live_records),
        'unique_live_logins': sorted(
            {record.get('twitch_login', '') for record in live_records if record.get('twitch_login', '')}
        ),
        'top_games': [
            {'game_name': game, 'live_count': count}
            for game, count in game_counter.most_common(5)
        ],
    }
    output_path = os.environ.get('SUMMARY_OUTPUT_PATH', 'summary.json')
    with open(output_path, 'w', encoding='utf-8') as handle:
        json.dump(summary, handle, indent=2, sort_keys=True)
    return summary

final_summary = aggregate_and_persist(twitch_enriched)

