CALENDLY_USER_URI = os.environ.get('CALENDLY_USER_URI', '')

def _calendly_mock_response():
    return {
        'collection': [
            {
                'uri': 'https://api.calendly.com/scheduled_events/EVENT123',
                'name': 'Customer onboarding call',
                'status': 'active',
