                'location': {'type': 'zoom', 'join_url': 'https://zoom.example.com/j/123'}
            },
            {
                'uri': 'https://api.calendly.com/scheduled_events/EVENT456',
                'name': 'Kickoff review',
                'status': 'canceled',
                'start_time': '2026-11-08T10:00:00.000000Z',
